// TestLoadPacks_DoesNotFollowSymlinkedSubdirs guards against accidentally
// recursing into directories the user did not intend to read. WalkDir uses
// lstat by default, so a symlinked subdirectory shows up as a symlink in
// the entry's Type() and is skipped before IsDir() is checked. Without
// this guard, an attacker who can plant a symlink inside .entire/redactors
// could redirect pack discovery to arbitrary parts of the filesystem.
func TestLoadPacks_DoesNotFollowSymlinkedSubdirs(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	outsideDir := t.TempDir()
	mustWrite(t, outsideDir, "outside.yaml", `
name: outside
version: 1.0.0
rules:
  - id: o
    regex: 'O+'
`)
	if err := os.Symlink(outsideDir, filepath.Join(dir, "linked")); err != nil {
		t.Skipf("symlink not supported: %v", err)
	}

	packs, err := LoadPacks(dir)
	if err != nil {
		t.Fatalf("LoadPacks: %v", err)
	}
	for _, p := range packs {
		if p.Name == "outside" {
			t.Fatalf("loaded pack reached via symlinked subdir: %s (from %s)", p.Name, p.sourcePath)
		}
	}
}

