	packs, err := LoadPacks(dir)
	if err != nil {
		t.Fatalf("LoadPacks: %v", err)
	}
	if len(packs) != 0 {
		t.Fatalf("symlinked pack should be skipped, loaded %d pack(s)", len(packs))
	}
}

