// TestAttach_AppliesCustomRedactionRules guards against a regression where
// runAttach forgot to call strategy.EnsureRedactionConfigured before
// redact.JSONLBytes, so user-defined `redaction.custom_redactions` and
// `.entire/redactors/*.yaml` packs silently no-op'd on the attach path even
// though they correctly apply to hook-driven checkpoint writes.
//
// The test configures a custom_redactions rule targeting a synthetic
// prefix that built-in detectors do not catch, attaches a transcript
// containing the pattern, and reads back the stored transcript blob to
// confirm the value was scrubbed.
func TestAttach_AppliesCustomRedactionRules(t *testing.T) {
	setupAttachTestRepo(t)

	// Replace the {"enabled": true} settings written by setupAttachTestRepo
	// with one that adds a custom rule. The pattern uses a unique prefix
	// and an all-lowercase tail so it does not match betterleaks rules or
	// trigger the entropy detector.
	repoDir := mustGetwd(t)
	settingsPath := filepath.Join(repoDir, ".entire", "settings.json")
	if err := os.WriteFile(settingsPath, []byte(`{
  "enabled": true,
  "redaction": {
    "custom_redactions": {
      "internal_project_id": "INTERNAL_PROJECT_ID_[a-z]{8,}"
    }
  }
}`), 0o600); err != nil {
		t.Fatal(err)
	}

	// Force the next EnsureRedactionConfigured call to re-read settings.
	strategy.ResetRedactionConfigurationForTest()
	t.Cleanup(func() {
		// Clear package-level redact state for sibling tests.
		redact.ConfigureCustomRules(redact.CustomRulesConfig{})
		strategy.ResetRedactionConfigurationForTest()
	})

	// Embed the secret as a tool_result so it survives transcript parsing
	// into the stored blob; the assistant text alone might not.
	const secret = "INTERNAL_PROJECT_ID_aaaaaaaa"
	sessionID := "test-attach-custom-redaction"
	setupClaudeTranscript(t, sessionID, `{"type":"user","message":{"role":"user","content":"audit the config"},"uuid":"uuid-1"}
{"type":"assistant","message":{"role":"assistant","content":[{"type":"tool_use","id":"tu_1","name":"Read","input":{"file_path":"config.txt"}}]},"uuid":"uuid-2"}
{"type":"user","message":{"content":[{"type":"tool_result","tool_use_id":"tu_1","content":"loaded `+secret+` from disk"}]},"uuid":"uuid-3"}
{"type":"assistant","message":{"role":"assistant","content":[{"type":"text","text":"Done."}]},"uuid":"uuid-4"}
`)

	var out bytes.Buffer
	if err := runAttach(context.Background(), &out, sessionID, agent.AgentNameClaudeCode, attachOptions{Force: true}); err != nil {
		t.Fatalf("runAttach failed: %v", err)
	}

	// Resolve the checkpoint ID from session state and read back the stored
	// transcript to confirm the secret was scrubbed before commit.
	store, err := session.NewStateStore(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	state, err := store.Load(context.Background(), sessionID)
	if err != nil || state == nil {
		t.Fatalf("session state not created: state=%v err=%v", state, err)
	}
	if state.LastCheckpointID.IsEmpty() {
		t.Fatal("expected LastCheckpointID after attach")
	}

	repo, err := git.PlainOpen(repoDir)
	if err != nil {
		t.Fatal(err)
	}
	cpStore := cpkg.NewGitStore(repo)
	content, err := cpStore.ReadSessionContent(context.Background(), state.LastCheckpointID, 0)
	if err != nil {
		t.Fatalf("ReadSessionContent: %v", err)
	}
	if content == nil {
		t.Fatal("nil session content")
	}
	transcript := string(content.Transcript)
	if strings.Contains(transcript, secret) {
		t.Errorf("custom_redactions rule did not fire; raw secret %q present in stored transcript:\n%s",
			secret, transcript)
	}
	if !strings.Contains(transcript, "REDACTED") {
		t.Errorf("expected REDACTED token in stored transcript; got:\n%s", transcript)
	}
}

